const b = $input.first().json.body || $input.first().json || {};
const resource = (b.resource || '').toString();
if (!['inbox', 'thread', 'webthread'].includes(resource)) throw new Error('unknown resource');
return [{ json: { resource: resource, filter: (b.filter || 'all').toString(),
  q: (b.q || '').toString(), id: parseInt(b.id) || 0,
  since: Math.max(0, parseInt(b.since) || 0), userId: (b.userId || b.externalUserId || '').toString(),
  channel: (b.channel || '').toString() } }];

const p = $input.first().json;
const q = (s) => (s || '').toString().replace(/'/g, "''");
let where = "c.status = 'open'";
if (p.filter === 'unread') where = "c.unread_count > 0 AND c.status = 'open'";
else if (p.filter === 'human') where = "c.bot_enabled = 0 AND c.status = 'open'";
else if (p.filter === 'closed') where = "c.status = 'closed'";
if (p.q) { const like = '%' + q(p.q) + '%'; where += ` AND (c.display_name LIKE '${like}' OR c.external_user_id LIKE '${like}' OR EXISTS (SELECT 1 FROM cd_messages m WHERE m.conversation_id = c.id AND m.content LIKE '${like}'))`; }
const items = `SELECT COALESCE(json_agg(row_to_json(t)), '[]') FROM (SELECT c.id, c.channel, c.external_user_id, c.display_name, c.picture_url, c.status, c.bot_enabled, c.unread_count, c.last_message_at, c.last_message_text, COALESCE(m.label, '') AS channel_label FROM cd_conversations c LEFT JOIN channel_map m ON m.channel_code = c.channel WHERE ${where} ORDER BY c.last_message_at IS NULL, c.last_message_at DESC, c.id DESC LIMIT 100) t`;
return [{ json: { sql: `SELECT (${items}) AS items, (SELECT COUNT(*) FROM cd_conversations WHERE status = 'open') AS open_count, (SELECT COUNT(*) FROM cd_conversations WHERE unread_count > 0 AND status = 'open') AS unread_count, (SELECT COUNT(*) FROM cd_conversations WHERE bot_enabled = 0 AND status = 'open') AS human_count, (SELECT COUNT(*) FROM cd_conversations WHERE status = 'closed') AS closed_count` } }];

const r = $input.first().json;
let items = r.items || [];
if (typeof items === 'string') { try { items = JSON.parse(items); } catch(e) { items = []; } }
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const linkify = (s) => esc(s).replace(/(https?:\/\/[^\s<]+)/g, '<a href="$1" target="_blank" rel="noopener noreferrer">$1</a>').replace(/\n/g, '<br>');
const tz = (ts) => { if (!ts) return null; const d = new Date(new Date(ts).getTime() + 7*3600*1000); const p = (n) => String(n).padStart(2, '0');
  return { hm: `${p(d.getUTCHours())}:${p(d.getUTCMinutes())}`, dmy: `${p(d.getUTCDate())}/${p(d.getUTCMonth()+1)}/${d.getUTCFullYear()}` }; };
const fmt = (row) => { const t = tz(row.created_at); return { id: row.id, sender: row.sender, type: row.message_type,
  content: row.content, html: linkify(row.content || ''),
  mediaUrl: row.media_url || null, mediaPreviewUrl: row.media_preview_url || null,
  stickerPackage: row.sticker_package || null, stickerId: row.sticker_id || null,
  status: row.status || 'ok', error: row.error_message || null,
  delivered: !!row.delivered_at, read: !!row.read_at, deleted: false,
  deliveredAt: row.delivered_at ? tz(row.delivered_at).hm : null,
  readAt: row.read_at ? tz(row.read_at).hm : null,
  time: t ? t.hm : '', date: t ? t.dmy : '' }; };
const cname = (c) => (c.display_name !== null && c.display_name !== '') ? c.display_name : ('id#' + c.id);
const srcname = (x) => { const l = (x.channel_label || '').toString().trim(); return l !== '' ? l : ((x.channel || '').toString()); };
const list = items.map(x => ({ id: x.id, name: cname(x), source: srcname(x),
  picture: x.picture_url, userId: x.external_user_id, status: x.status,
  botEnabled: parseInt(x.bot_enabled) === 1, unread: parseInt(x.unread_count) || 0,
  preview: x.last_message_text || '',
  time: x.last_message_at ? (() => { const t = tz(x.last_message_at); return t.dmy.slice(0, 5) + ' ' + t.hm; })() : '' }));
return [{ json: { ok: true, items: list, counts: { open: parseInt(r.open_count) || 0,
  unread: parseInt(r.unread_count) || 0, human: parseInt(r.human_count) || 0, closed: parseInt(r.closed_count) || 0 } } }];

const p = $input.first().json;
if (!p.id) throw new Error('missing id');
return [{ json: { id: p.id, since: p.since, sql: `SELECT * FROM cd_conversations WHERE id = ${p.id} LIMIT 1` } }];

const t = $('Q TConv').first().json;
const id = parseInt(t.id) || 0;
if (!id) throw new Error('missing id');
const since = Math.max(0, parseInt(t.since) || 0);
return [{ json: { id: id, since: since, sql: `SELECT id, sender, content, message_type, media_url, media_preview_url, sticker_package, sticker_id, status, error_message, delivered_at, read_at, created_at FROM cd_messages WHERE conversation_id = ${id} AND deleted_at IS NULL` + (since > 0 ? ` AND id > ${since}` : '') + ` ORDER BY id DESC LIMIT 200` } }];

let conv = null;
try { conv = $('Run TConv').first().json; if (conv.channel === undefined) conv = null; } catch(e) { conv = null; }
if (!conv) return [{ json: { ok: false, error: 'conv-missing' } }];
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const linkify = (s) => esc(s).replace(/(https?:\/\/[^\s<]+)/g, '<a href="$1" target="_blank" rel="noopener noreferrer">$1</a>').replace(/\n/g, '<br>');
const tz = (ts) => { if (!ts) return null; const d = new Date(new Date(ts).getTime() + 7*3600*1000); const p = (n) => String(n).padStart(2, '0');
  return { hm: `${p(d.getUTCHours())}:${p(d.getUTCMinutes())}`, dmy: `${p(d.getUTCDate())}/${p(d.getUTCMonth()+1)}/${d.getUTCFullYear()}` }; };
const fmt = (row) => { const t = tz(row.created_at); return { id: row.id, sender: row.sender, type: row.message_type,
  content: row.content, html: linkify(row.content || ''),
  mediaUrl: row.media_url || null, mediaPreviewUrl: row.media_preview_url || null,
  stickerPackage: row.sticker_package || null, stickerId: row.sticker_id || null,
  status: row.status || 'ok', error: row.error_message || null,
  delivered: !!row.delivered_at, read: !!row.read_at, deleted: false,
  deliveredAt: row.delivered_at ? tz(row.delivered_at).hm : null,
  readAt: row.read_at ? tz(row.read_at).hm : null,
  time: t ? t.hm : '', date: t ? t.dmy : '' }; };
const cname = (c) => (c.display_name !== null && c.display_name !== '') ? c.display_name : ('id#' + c.id);
const msgs = $('Run TMsgs').all().map(r => r.json).filter(r => r.sender !== undefined).sort((a, b) => a.id - b.id);
const since = (() => { try { return $('Q TMsgs').first().json.since || 0; } catch(e) { return 0; } })();
const lastId = msgs.reduce((m, x) => Math.max(m, x.id), since);
const ct = tz(conv.created_at);
return [{ json: { ok: true,
  conversation: { id: conv.id, name: cname(conv), picture: conv.picture_url, userId: conv.external_user_id,
    channel: conv.channel, status: conv.status, botEnabled: parseInt(conv.bot_enabled) === 1,
    since: ct ? (ct.dmy + ' ' + ct.hm) : '' },
  messages: msgs.map(fmt), lastId: lastId } }];

const p = $input.first().json;
if (!/^WEB_[A-Za-z0-9_-]{1,64}$/.test(p.userId)) throw new Error('bad user');
const q = (s) => (s || '').toString().replace(/'/g, "''");
const ch = (p.channel === 'shopweb') ? 'shopweb' : 'web';
return [{ json: { userId: p.userId, since: p.since, channel: ch, sql: `SELECT * FROM cd_conversations WHERE channel = '${ch}' AND external_user_id = '${q(p.userId)}' LIMIT 1` } }];

const t = $('Q WConv').first().json;
const q = (s) => (s || '').toString().replace(/'/g, "''");
const since = Math.max(0, parseInt(t.since) || 0);
const ch = (t.channel === 'shopweb') ? 'shopweb' : 'web';
return [{ json: { since: since, sql: `SELECT id, sender, content, message_type, created_at FROM cd_messages WHERE conversation_id = COALESCE((SELECT id FROM cd_conversations WHERE channel = '${ch}' AND external_user_id = '${q(t.userId)}' LIMIT 1), -1) AND deleted_at IS NULL` + (since > 0 ? ` AND id > ${since}` : '') + ` ORDER BY id DESC LIMIT 100` } }];

let conv = null;
try { conv = $('Run WConv').first().json; if (conv.channel === undefined) conv = null; } catch(e) { conv = null; }
const since = (() => { try { return $('Q WConv').first().json.since || 0; } catch(e) { return 0; } })();
if (!conv) return [{ json: { ok: true, conversationId: 0, messages: [], lastId: since } }];
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const linkify = (s) => esc(s).replace(/(https?:\/\/[^\s<]+)/g, '<a href="$1" target="_blank" rel="noopener noreferrer">$1</a>').replace(/\n/g, '<br>');
const tz = (ts) => { if (!ts) return null; const d = new Date(new Date(ts).getTime() + 7*3600*1000); const p = (n) => String(n).padStart(2, '0');
  return { hm: `${p(d.getUTCHours())}:${p(d.getUTCMinutes())}`, dmy: `${p(d.getUTCDate())}/${p(d.getUTCMonth()+1)}/${d.getUTCFullYear()}` }; };
const fmt = (row) => { const t = tz(row.created_at); return { id: row.id, sender: row.sender, type: row.message_type,
  content: row.content, html: linkify(row.content || ''),
  mediaUrl: row.media_url || null, mediaPreviewUrl: row.media_preview_url || null,
  stickerPackage: row.sticker_package || null, stickerId: row.sticker_id || null,
  status: row.status || 'ok', error: row.error_message || null,
  delivered: !!row.delivered_at, read: !!row.read_at, deleted: false,
  deliveredAt: row.delivered_at ? tz(row.delivered_at).hm : null,
  readAt: row.read_at ? tz(row.read_at).hm : null,
  time: t ? t.hm : '', date: t ? t.dmy : '' }; };
const cname = (c) => (c.display_name !== null && c.display_name !== '') ? c.display_name : ('id#' + c.id);
const msgs = $('Run WMsgs').all().map(r => r.json).filter(r => r.sender !== undefined).sort((a, b) => a.id - b.id);
const lastId = msgs.reduce((m, x) => Math.max(m, x.id), since);
return [{ json: { ok: true, conversationId: conv.id, botEnabled: parseInt(conv.bot_enabled) === 1,
  status: conv.status, messages: msgs.map(m => { const f = fmt(m); return { id: f.id, sender: f.sender, type: f.type, text: f.content, time: f.time }; }), lastId: lastId } }];
